#!/usr/bin/env bash
# Rebuild every graph-experiment training set with the data_io pipeline.
# Epoch counts equal `epochs` in the matching config/cfg_*.yaml (one epoch_N/ dir per training epoch).
#
#   bash scripts/graphs/prepare_all.sh              # everything
#   ONLY="graphqa metaqa" bash scripts/graphs/prepare_all.sh
#
# Raw sources: data/graphs/ (copied from HRM-Text-for-Graphs/data and graphqa_scaled/jsonl). The
# GraphQA generator itself lives in Graph-Representation-Learning-for-LLM; pointer chasing is
# regenerated by scripts/graphs/make_pointer_chasing.py; GSM8k/MATH/MMLU are pulled from the HF hub.
set -euo pipefail

cd "$(dirname "$0")/../.."
PY=${PY:-.venv/bin/python}
D=data/graphs
want() { [[ -z "${ONLY:-}" || " $ONLY " == *" $1 "* ]]; }
prep() { want "$1" && bash scripts/graphs/prepare_dataset.sh "$@"; return 0; }

# name                 train JSONL                                          epochs  (config)
prep graphqa           $D/graphqa/hrm-text/standard/train.jsonl            20      # cfg_graphqa
prep graphqa_scaled    $D/graphqa_scaled/train-1m/train.jsonl              4       # cfg_graphqa_scaled
prep metaqa            $D/metaqa/hrm-text/standard/train.jsonl             20      # cfg_metaqa
prep kqapro            $D/kqapro/hrm-text/standard/train.jsonl             6       # cfg_kqapro
prep pointer           $D/pointer/hrm-text/standard/train.jsonl            4       # cfg_pointer
prep pointer2          $D/pointer2/hrm-text/standard/train.jsonl           3       # cfg_pointer2

# MetaQA multi-answer variants: baseline JSON -> hrm-text JSONL first.
for v in metaqa-gold-1 metaqa-gold-5 metaqa-gold-10 metaqa-retrieved-1; do
  want "$v" || continue
  [[ -f $D/$v/hrm-text/standard/train.jsonl ]] || \
    "$PY" scripts/graphs/format_graphqa_to_hrm.py --input-dir $D/$v/baseline --output-dir $D/$v/hrm-text
  prep "$v" $D/$v/hrm-text/standard/train.jsonl 20                         # cfg_metaqa data.path override
done

# Benchmarks (direct answers, prompts built with evaluation/benchmarks.py helpers).
for b in gsm8k:15 math:30 mmlu:5; do
  name=${b%%:*}; epochs=${b##*:}
  want "$name" || continue
  [[ -f $D/$name/hrm-text/train.jsonl ]] || \
    "$PY" scripts/graphs/prepare_benchmark_data.py --benchmark "$name" --output $D/$name/hrm-text/train.jsonl
  prep "$name" $D/$name/hrm-text/train.jsonl "$epochs"                     # cfg_$name
done
